import { useState, useContext, useRef, useEffect } from 'react';
import { AppCtx } from '../App';
import { getAllSubmissions, approveKYC, rejectKYC, getSubmissionDetails } from '../apis/adminApi';

const sMap = { Pending:'b-pending','In Review':'b-review',Approved:'b-approved',Failed:'b-failed' };
const Badge = ({s}) => <span className={`badge ${sMap[s]||'b-pending'}`}>{s}</span>;
function Toast({msg,type}){ return <div className={`toast ${type==='ok'?'ok':'err'}`}>{type==='ok'?'✅':'❌'} {msg}</div>; }

function Skeleton({ w='100%', h=16, radius=6, style={} }) {
  return <div style={{ width:w, height:h, borderRadius:radius, background:'linear-gradient(90deg,var(--skeleton-a,#E2E8F0) 25%,var(--skeleton-b,#F1F5F9) 50%,var(--skeleton-a,#E2E8F0) 75%)', backgroundSize:'200% 100%', animation:'shimmer 1.4s infinite', ...style }}/>;
}

/* Normalize status string from API */
function normalizeStatus(s) {
  if (!s) return 'Pending';
  const m = { pending:'Pending', approved:'Approved', rejected:'Failed', failed:'Failed', 'in-review':'In Review', 'in_review':'In Review', 'In Review':'In Review' };
  return m[s] || s;
}

function getInitials(name) {
  if (!name) return '?';
  return name.split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2);
}
const COLORS = ['#6C63FF','#FF6584','#43E97B','#FA8231','#E74C3C','#3498DB','#9B59B6','#1ABC9C','#E67E22','#2ECC71'];

/* ── Doc preview popup ── */
function openDocPreview({ title, emoji, color, headerBg, fields, note, userName }) {
  const rows = fields.map(([l,v]) => {
    const mono = ['Aadhaar No.','PAN No.','Account No.','IFSC Code','IFSC'].includes(l);
    return `<tr><td style="padding:11px 16px;color:#64748B;font-size:13px;font-weight:500;border-bottom:1px solid #F1F5F9;width:40%">${l}</td><td style="padding:11px 16px;color:#0D1B3E;font-size:13px;font-weight:700;border-bottom:1px solid #F1F5F9;font-family:${mono?'monospace':'inherit'}">${v}</td></tr>`;
  }).join('');
  const noteHtml = note ? `<div style="padding:16px 32px"><div style="padding:12px 16px;background:#FFFBEB;border:1px solid #FDE68A;border-radius:10px;font-size:12.5px;color:#92400E">${note}</div></div>` : '';
  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>${title} — ${userName}</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#F8FAFC;min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:40px 20px}.card{background:#fff;border-radius:20px;box-shadow:0 8px 40px rgba(0,0,0,0.10);width:100%;max-width:600px;overflow:hidden}.header{background:${headerBg};padding:32px;display:flex;align-items:center;gap:18px}.icon-wrap{width:64px;height:64px;border-radius:16px;background:rgba(255,255,255,0.25);display:flex;align-items:center;justify-content:center;font-size:34px;flex-shrink:0}.header-text h1{font-size:22px;font-weight:800;color:#fff}.header-text p{font-size:13px;color:rgba(255,255,255,0.75);margin-top:4px}.badge{display:inline-flex;align-items:center;gap:5px;background:rgba(255,255,255,0.2);border:1px solid rgba(255,255,255,0.35);border-radius:20px;padding:4px 12px;font-size:11.5px;color:#fff;font-weight:600;margin-top:10px}.watermark{padding:14px 32px;background:rgba(255,255,255,0.08);border-bottom:1px solid rgba(255,255,255,0.12);font-size:11px;color:rgba(255,255,255,0.55);font-weight:600;letter-spacing:1.5px;text-transform:uppercase}table{width:100%;border-collapse:collapse}.footer{padding:20px 32px;background:#F8FAFC;border-top:1px solid #E2E8F0;display:flex;justify-content:space-between;align-items:center}.footer-left{font-size:11.5px;color:#94A3B8}.stamp-inner{border:3px solid ${color};border-radius:12px;padding:8px 18px;color:${color};font-size:13px;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:0.85;transform:rotate(-8deg);display:inline-block}</style></head><body><div style="width:100%;max-width:600px;margin-bottom:16px;display:flex;justify-content:space-between"><div style="font-size:13px;color:#64748B">PayO Admin Portal — Document Preview</div><div style="font-size:12px;color:#94A3B8">For internal review only</div></div><div class="card"><div class="header"><div class="icon-wrap">${emoji}</div><div class="header-text"><h1>${title}</h1><p>Submitted by <strong>${userName}</strong></p><div class="badge">✓ Verified &amp; Submitted</div></div></div><div class="watermark">🔒 Confidential — Authorised Admin Access Only</div><table>${rows}</table>${noteHtml}<div class="footer"><div class="footer-left">Submitted via PayO App &bull; All data encrypted</div><div class="stamp"><div class="stamp-inner">Submitted ✓</div></div></div></div></body></html>`;
  const blob = new Blob([html], { type:'text/html' });
  window.open(URL.createObjectURL(blob), '_blank');
}

/* ── PreviewThumb ── */
function PreviewThumb({ label, emoji, color, headerBg, onClick }) {
  const [hover, setHover] = useState(false);
  return (
    <div onClick={onClick} onMouseEnter={()=>setHover(true)} onMouseLeave={()=>setHover(false)}
