/* ── Review Modal — shows detail/docs/action for a KYC record ── */
function Modal({ user, onClose, onApprove, onReject }) {
  const [tab, setTab] = useState('details');
  const [reason, setReason] = useState('');
  const [detailLoading, setDetailLoading] = useState(false);
  const [details, setDetails] = useState(null);

  useEffect(() => {
    if (!user) return;
    const kycId = user._id || user.id || user.kycId;
    if (!kycId) return;
    setDetailLoading(true);
    getSubmissionDetails(kycId)
      .then(res => {
        const d = res.data?.data || res.data || {};
        setDetails(d);
      })
      .catch(() => {})
      .finally(() => setDetailLoading(false));
  }, [user]);

  if (!user) return null;

  const name   = user.userName || user.name || user.user?.name || 'Unknown';
  const userId = user.userId   || user._id  || user.id || '';
  const status = normalizeStatus(user.status || user.kycStatus);
  const isFailed = status === 'Failed';
  const initials = user.initials || getInitials(name);
  const color    = user.color   || COLORS[0];

  // Build document fields from API details or user object
  const docs = details?.documents || user.documents || {};
  const hasFullDocs = !!(docs?.aadhaar && docs?.pan && docs?.bankDocs);

  const preview = (cfg) => openDocPreview({ ...cfg, userName: name });

  return (
    <div className="overlay" onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div className="modal" style={{ maxWidth:860 }}>
        <div className="modal-head">
          <div style={{ display:'flex', alignItems:'center', gap:12 }}>
            <div className="avatar" style={{ background:color, width:46, height:46, borderRadius:12, fontSize:16 }}>{initials}</div>
            <div>
              <h3>{name}</h3>
              <div style={{ fontSize:13, color:'var(--gray-400)', marginTop:2, display:'flex', alignItems:'center', gap:8 }}>
                <span>{String(userId).slice(-10)}</span>
                <Badge s={status}/>
              </div>
            </div>
          </div>
          <button className="btn btn-ghost icon-btn" onClick={onClose}>
            <svg width="15" height="15" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <div className="modal-tabs">
          {[['details','Details'],['documents','Documents'],['action','Take Action']].map(([key,label]) => (
            <button key={key} className={`mtab${tab===key?' act':''}`} onClick={()=>setTab(key)}>{label}</button>
          ))}
        </div>

        <div className="modal-body">
          {detailLoading && (
            <div style={{ padding:'32px', textAlign:'center', color:'var(--gray-400)', fontSize:14 }}>
              <div style={{ width:28, height:28, border:'3px solid var(--gray-200)', borderTopColor:'#3B82F6', borderRadius:'50%', animation:'spin 0.8s linear infinite', margin:'0 auto 12px' }}/>
              Loading details...
              <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
            </div>
          )}

          {!detailLoading && tab === 'details' && (
            <>
              <div style={{ marginBottom:20 }}>
                <div className="section-title">Personal Information</div>
                <div className="detail-grid">
                  {[
                    ['Full Name', name],
                    ['User ID', String(userId).slice(-12)],
                    ['Email', details?.email || user.email || user.user?.email || '—'],
                    ['Phone', details?.phone || user.phone || user.user?.phone || '—'],
                    ['Date of Birth', details?.dob || user.dob || '—'],
                    ['Submitted On', user.createdAt || user.submittedAt ? new Date(user.createdAt||user.submittedAt).toLocaleString('en-IN') : '—'],
                  ].map(([l,v]) => (
                    <div className="detail-item" key={l}><label>{l}</label><span>{v}</span></div>
                  ))}
                </div>
              </div>
              {(details?.address || user.address) && (
                <div style={{ marginBottom:16 }}>
                  <div className="section-title">Address</div>
                  <div style={{ fontSize:13.5, color:'var(--navy)', fontWeight:500 }}>{details?.address || user.address}</div>
                </div>
              )}
              {isFailed && (user.rejectionReason || details?.rejectionReason) && (
                <div style={{ background:'#FEF2F2', border:'1px solid #FECACA', borderRadius:10, padding:'12px 14px' }}>
                  <div style={{ fontSize:10.5, fontWeight:700, color:'#DC2626', letterSpacing:'0.5px', textTransform:'uppercase', marginBottom:4 }}>Rejection Reason</div>
                  <div style={{ fontSize:13, color:'#7F1D1D' }}>{user.rejectionReason || details?.rejectionReason}</div>
                </div>
              )}
            </>
          )}

          {!detailLoading && tab === 'documents' && (
            <>
              {isFailed && (
                <div style={{ background:'#FEF2F2', border:'1px solid #FECACA', borderRadius:10, padding:'10px 14px', marginBottom:14, fontSize:13, color:'#991B1B', display:'flex', alignItems:'center', gap:8 }}>
                  <span>⚠️</span><span>This KYC was <strong>rejected</strong>. Review all documents carefully before re-approving.</span>
