                      />
                      <IdDocCard title="PAN Card" emoji="💳"
                        fields={[['Name',docs.pan.name||'—'],['DOB',docs.pan.dob||'—'],['PAN No.',docs.pan.number||'—']]}
                        flagged={isFailed} accentColor="#8B5CF6" accentBg="linear-gradient(135deg,#F5F3FF,#EDE9FE)"
                        onPreview={()=>preview({ title:'PAN Card', emoji:'💳', color:'#8B5CF6', headerBg:'linear-gradient(135deg,#8B5CF6,#A78BFA)', fields:[['Full Name',docs.pan.name],['Date of Birth',docs.pan.dob],['PAN No.',docs.pan.number]], note:'PAN number is used for tax identification in India.' })}
                      />
                    </div>
                  </div>
                  <div style={{ marginBottom:20 }}>
                    <SectionDivider icon="🤳" label="Live Selfie" bg="#F0FDF4"/>
                    <SelfieCard flagged={isFailed}
                      onPreview={()=>preview({ title:'Live Selfie', emoji:'🤳', color:'#10B981', headerBg:'linear-gradient(135deg,#10B981,#34D399)', fields:[['Captured By',name],['Method','In-App Liveness Check'],['Status','Verified']], note:'Selfie captured live in the PayO app using liveness detection.' })}
                    />
                  </div>
                  {docs.bankDocs && (
                    <div style={{ marginBottom:20 }}>
                      <SectionDivider icon="🏦" label="Bank Documents" bg="#F0F9FF"/>
                      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:12 }}>
                        <BankDocCard icon="🏦" title="Cancel Cheque" subtitle={docs.bankDocs.cancelCheque?.bankName||'—'}
