                          fields={[['Bank',docs.bankDocs.cancelCheque?.bankName||'—'],['Account No.',docs.bankDocs.cancelCheque?.accountNumber||'—'],['IFSC',docs.bankDocs.cancelCheque?.ifsc||'—']]}
                          flagged={isFailed}
                          onPreview={()=>preview({ title:'Cancel Cheque', emoji:'🏦', color:'#0EA5E9', headerBg:'linear-gradient(135deg,#0EA5E9,#38BDF8)', fields:[['Bank Name',docs.bankDocs.cancelCheque?.bankName||'—'],['Account No.',docs.bankDocs.cancelCheque?.accountNumber||'—'],['IFSC Code',docs.bankDocs.cancelCheque?.ifsc||'—'],['Account Holder',docs.bankDocs.cancelCheque?.accountHolder||name]] })}
                        />
                        <BankDocCard icon="📄" title="Bank Statement" subtitle={docs.bankDocs.bankStatement?.period||'—'}
                          accentColor="#8B5CF6" accentBg="linear-gradient(135deg,#F5F3FF,#EDE9FE)"
                          fields={[['Bank',docs.bankDocs.bankStatement?.bankName||'—'],['Period',docs.bankDocs.bankStatement?.period||'—'],['Pages',(docs.bankDocs.bankStatement?.pages||'?')+' pages']]}
                          flagged={isFailed}
                          onPreview={()=>preview({ title:'Bank Statement', emoji:'📄', color:'#8B5CF6', headerBg:'linear-gradient(135deg,#8B5CF6,#A78BFA)', fields:[['Bank Name',docs.bankDocs.bankStatement?.bankName||'—'],['Period',docs.bankDocs.bankStatement?.period||'—'],['Account Holder',name]] })}
                        />
                        <BankDocCard icon="📒" title="Passbook" subtitle={docs.bankDocs.passbook?.bankName||'—'}
                          accentColor="#F59E0B" accentBg="linear-gradient(135deg,#FFFBEB,#FEF3C7)"
                          fields={[['Bank',docs.bankDocs.passbook?.bankName||'—'],['Period',docs.bankDocs.passbook?.period||'—']]}
                          flagged={isFailed}
                          onPreview={()=>preview({ title:'Passbook', emoji:'📒', color:'#F59E0B', headerBg:'linear-gradient(135deg,#F59E0B,#FCD34D)', fields:[['Bank Name',docs.bankDocs.passbook?.bankName||'—'],['Account Holder',name]] })}
                        />
